      guides.push(guide('change-to-f-5-20','birth',['F-5-20 · grant of status to a child born in Korea','F-5-20 · कोरियामा जन्मेको बच्चाको बसाइ अनुमति'],['Use the newborn grant-of-status procedure, normally within 90 days. This is not an adult change of visa; the parent and child must meet the F-5-20 criteria.','सामान्यतया जन्मेको ९० दिनभित्र बच्चाको बसाइ अनुमति दिने प्रक्रिया अपनाउनुहोस्। यो वयस्कको भिसा परिवर्तन होइन; अभिभावक र बच्चाको F-5-20 योग्यता पूरा हुनुपर्छ।'],[application(['체류자격 부여 (grant of status)','체류자격 부여 (बसाइ अनुमति दिने)']),passport,residence,photo,...statusDocuments(visa.id)],{visa:visa.id}));
